--- a/src/rules.js
+++ b/src/rules.js
@@ -12,17 +12,28 @@ const DIRECTION = {
   transport: 1,
   utilities: 1,
   dining: 1,
+  refund: -1,
 };

+// Every known category must be assigned a direction explicitly — a category present in
+// KNOWN_CATEGORIES but absent here used to silently default to +1 (spend), which is how a
+// refund category got counted as spend instead of money back. Fail loudly instead.
+for (const category of KNOWN_CATEGORIES) {
+  if (!(category in DIRECTION)) {
+    throw new Error(`rules.js: category "${category}" has no DIRECTION entry`);
+  }
+}
+
 function normalizeCategory(raw) {
   const category = String(raw || '').trim().toLowerCase();
   return KNOWN_CATEGORIES.includes(category) ? category : 'other';
 }

-// Signed amount: positive means money left the account.
+// Signed amount: positive means money left the account. Unclassified ("other") rows
+// default to spend, same conservative behavior as before.
 function signedAmount(record) {
   const category = normalizeCategory(record.category);
-  const direction = DIRECTION[category] || 1;
+  const direction = category === 'other' ? 1 : DIRECTION[category];
   return Math.abs(record.amount) * direction;
 }

